/**
 * "Laporan" (FR-LP1–LP5, design `ogfhy`): the header line ("September 2026 · Final · 1–30 Sep · dibandingkan dengan
 * Agustus 2026 · 121 transaksi"), the period switcher, the KPI strip with its comparisons, and the sections — money
 * flow, spending, goals, largest transactions, subscriptions, net worth, notes, and the saved reports. The first
 * render shows the latest final report without a fetch; every other selection is generated by `viewReport`, with the
 * old data kept on screen under "Menghitung ulang…", an error state with "Coba lagi", and the new user's timeline
 * when nothing has been saved yet.
 */
import { useEffect, useRef, useState, type ReactNode } from 'react';
import type { ReportFileMeta } from '@wf/db/report-files';
import type { ReportSummary, ReportView } from '@wf/db/reports';
import type { LocalDate } from '@wf/domain/period';
import type { Locale } from '@wf/i18n/locale';
import { m } from '@wf/i18n/messages';
import { formatDateTime } from '@wf/i18n/format';
import { Download } from 'lucide-react';
import { PageState } from '@wf/ui/page-state';
import { shortRange } from '../dashboard/dashboard-format.ts';
import { PageHeader } from '../page-header.tsx';
import { Button } from '../form.tsx';
import { RichMessage } from '../rich-message.tsx';
import { listReportFiles } from '../../server/fn/report-export.ts';
import { viewReport } from '../../server/fn/reports.ts';
import { FlowSection } from './reports-flow.tsx';
import { GoalsSection } from './reports-goals.tsx';
import { LargestSection } from './reports-largest.tsx';
import { monthlyOptions, neutralLabel, requestOf, selectionLabel, type ReportSelection } from './reports-model.ts';
import { NetWorthSection } from './reports-networth.tsx';
import { ReportsPicker } from './reports-picker.tsx';
import { ReportsExportDialog } from './reports-export.tsx';
import { SavedSection } from './reports-saved.tsx';
import { ReportsKpis } from './reports-kpis.tsx';
import { ImmutabilityBanner, ReportsEmpty, ReportsError, StatusBadge } from './reports-states.tsx';
import { SpendingSection } from './reports-spending.tsx';
import { NotesSection, SubsSection } from './reports-subs.tsx';

export interface ReportsPageProps {
  /** Saved reports, newest first. */
  readonly reports: ReportSummary[];
  readonly latestFinal: ReportView | null;
  readonly today: LocalDate;
  readonly timeZone: string;
  readonly locale: Locale;
}

/** A monthly final always carries its period id; the id fallback keeps the type honest if a row is ever corrupt. */
function periodIdOf(view: ReportView): string {
  return view.periodId ?? view.id;
}

/** "Dibuat 1 Okt 2026, 09.00". */
function generatedAt(view: ReportView, timeZone: string, locale: Locale): string {
  return formatDateTime(view.generatedAt, locale, timeZone);
}

export function ReportsPage({ reports, latestFinal, today, timeZone, locale }: ReportsPageProps): ReactNode {
  const [selection, setSelection] = useState<ReportSelection | null>(
    latestFinal === null ? null : { kind: 'monthly', id: latestFinal.id, periodId: periodIdOf(latestFinal) },
  );
  const [view, setView] = useState<ReportView | null>(latestFinal);
  const [phase, setPhase] = useState<'idle' | 'recalculating' | 'error'>('idle');
  const [failedLabel, setFailedLabel] = useState('');
  const [exporting, setExporting] = useState(false);
  /** The stored export files ("Laporan tersimpan"'s downloads), `null` until the first fetch answered. */
  const [files, setFiles] = useState<ReportFileMeta[] | null>(null);
  const pending = useRef(0);

  /** The saved files list, fetched on mount and after every queued export. */
  const reloadFiles = () => {
    void listReportFiles({ data: {} })
      .then((result) => {
        if (result.ok) setFiles(result.value);
      })
      .catch(() => undefined);
  };
  useEffect(() => {
    reloadFiles();
  }, []);

  const load = async (next: ReportSelection) => {
    const nextRequest = requestOf(next);
    const token = ++pending.current;
    setSelection(next);
    setPhase('recalculating');
    const result = await viewReport({ data: nextRequest }).catch(() => null);
    if (pending.current !== token) return;
    if (result?.ok === true) {
      setView(result.value);
      setPhase('idle');
    } else {
      setFailedLabel(selectionLabel(next, reports, latestFinal, locale, today));
      setPhase('error');
    }
  };

  /** Without a saved final report but with saved reports, the newest one opens on mount. */
  useEffect(() => {
    if (latestFinal !== null || reports.length === 0) return;
    const newest = reports[0];
    if (newest === undefined || newest.kind !== 'monthly') return;
    const periodId = monthlyOptions(reports, latestFinal).find((option) => option.id === newest.id)?.periodId;
    if (periodId === null) return;
    void Promise.resolve().then(() => {
      void load({ kind: 'monthly', id: newest.id, periodId: periodId as string });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps -- the home data of the mount; selections reload explicitly
  }, []);

  const retry = () => {
    // An error is only reachable through `load`, which always sets the selection first.
    void load(selection as ReportSelection);
  };

  const recalc = phase === 'recalculating';

  /** The saved rows the page can fetch a full view for: their period id is in hand. */
  const selectable = new Map<string, ReportSelection>();
  for (const option of monthlyOptions(reports, latestFinal)) {
    if (option.periodId !== null) {
      selectable.set(option.id, { kind: 'monthly', id: option.id, periodId: option.periodId });
    }
  }

  const empty = latestFinal === null && reports.length === 0;
  const compare =
    view?.compare === undefined || view.compare === null ? null : neutralLabel(view.compare.label, locale, today);
  const header =
    view === null ? null : (
      <span className="flex flex-wrap items-center gap-x-2 gap-y-1">
        {neutralLabel(view.label, locale, today)}
        <StatusBadge status={view.status} />
        <span aria-hidden="true" className="text-subtle">
          ·
        </span>
        {shortRange(view.range, locale, today)}
        {compare === null ? null : (
          <>
            <span aria-hidden="true" className="text-subtle">
              ·
            </span>
            <RichMessage message={m.reports_compared_with} slots={{ period: compare }} />
          </>
        )}
        <span aria-hidden="true" className="text-subtle">
          ·
        </span>
        {m.reports_tx_count({ count: view.totals.txCount })}
        <span aria-hidden="true" className="text-subtle">
          ·
        </span>
        {m.reports_generated({ at: generatedAt(view, timeZone, locale) })}
      </span>
    );

  return (
    <div className="flex flex-col gap-4">
      <PageHeader
        breadcrumb={[m.breadcrumb_finance(), m.reports_title()]}
        title={m.reports_title()}
        description={empty ? m.reports_empty_subtitle() : header}
        actions={
          recalc ? (
            <PageState kind="refreshing" title={m.reports_recalculating()} />
          ) : view === null ? undefined : (
            <Button
              size="sm"
              onClick={() => {
                setExporting(true);
              }}
            >
              <Download aria-hidden="true" className="size-3.5" />
              {m.report_export_title()}
            </Button>
          )
        }
      />
      {exporting && view !== null ? (
        <ReportsExportDialog view={view} locale={locale} onOpenChange={setExporting} onExported={reloadFiles} />
      ) : null}
      {view === null ? null : view.status === 'final' ? <ImmutabilityBanner /> : null}
      {empty ? (
        <ReportsEmpty today={today} locale={locale} />
      ) : (
        <>
          <ReportsPicker
            reports={reports}
            latestFinal={latestFinal}
            today={today}
            locale={locale}
            selection={selection}
            onSelect={(next) => void load(next)}
          />
          {phase === 'error' ? (
            <ReportsError label={failedLabel} onRetry={retry} />
          ) : view === null ? (
            <section className="rounded-[12px] border border-border bg-card">
              <PageState kind="loading" title={m.reports_loading()} />
            </section>
          ) : (
            <div aria-busy={recalc} className={`flex flex-col gap-4 transition-opacity ${recalc ? 'opacity-50' : ''}`}>
              <ReportsKpis view={view} locale={locale} today={today} />
              <FlowSection view={view} locale={locale} />
              <SpendingSection view={view} locale={locale} />
              <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
                <GoalsSection view={view} locale={locale} />
                <LargestSection view={view} locale={locale} />
                <SubsSection view={view} locale={locale} />
                <NetWorthSection view={view} locale={locale} />
              </div>
              <NotesSection view={view} locale={locale} />
              <SavedSection
                reports={reports}
                selectedId={selection?.kind === 'monthly' ? selection.id : null}
                selectable={selectable}
                locale={locale}
                today={today}
                timeZone={timeZone}
                files={files}
                onSelect={(next) => void load(next)}
              />
            </div>
          )}
        </>
      )}
    </div>
  );
}
